sys_script_include.script:
var BasesUtils = Class.create();
BasesUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkManagerBase: function() {
        var manager = this.getParameter('sysparm_manager');
        var arr = [];
        var grManager = new GlideRecord('x_1488662_bases_bases');
        grManager.addActiveQuery();
        grManager.addQuery('base_manager', manager);
        grManager.query();

        while (grManager.next()) {
            arr.push(grManager.sys_id.toString());
        }

        return arr.length > 0 ? arr.join(',') : 'none';
    },

    refQualTask7: function() {
        var basesNotToBeShown = [];
        var grBasesList = new GlideRecord('x_1488662_bases_admission');
        grBasesList.addQuery("opened_by", gs.getUserID());
        // grBasesList.addQuery("state", "!=", 4);
		grBasesList.addEncodedQuery("stateIN8,2");

        grBasesList.query();

        while (grBasesList.next()) {
            basesNotToBeShown.push(grBasesList.base.toString()); 
        }

        if (basesNotToBeShown.length > 0) {
            return "sys_idINnone";
        }

        var basesToBeShown = [];
        var grShow = new GlideRecord("x_1488662_bases_bases");
        grShow.addQuery('max_capacity', ">", 0); 
        grShow.query();

        while (grShow.next()) {
            var baseSysId = grShow.getUniqueValue();
            basesToBeShown.push(baseSysId);
        }

        return "sys_idIN" + (basesToBeShown.length > 0 ? basesToBeShown.join(",") : "none");
    },

    type: 'BasesUtils'
});
